+  late MemoryExecutionEnv env;
+  late FakeCliIO io;
+
+  setUp(() {
+    env = MemoryExecutionEnv(cwd: '/work');
+    io = FakeCliIO();
+  });
+
+  tearDown(() => io.close());
+
+  AgentCli cliFor(StreamFunction streamFunction) {
+    return AgentCli(
+      config: AgentCliConfig(
+        model: testModel,
+        apiKey: '[REDACTED:Sensitive Value]',
+        env: env,
+        sessionRoot: '/sessions',
