+  Future<void> seedNamedSession(String name) async {
+    final repo = JsonlSessionRepo(fs: env, sessionsRoot: '/sessions');
+    final session = await repo.create(
+      JsonlSessionCreateOptions(cwd: '/work', metadata: {'agent': 'cli'}),
+    );
