    if (session == null) {
      io.writeln('no active session');
      return;
    }
    io.writeln(_style.dim('following session records — Ctrl+C to stop'));
    final tailer = TrajectoryTailer(width: _trajectoryWidth);
    final interrupted = io.interrupts.first.then((_) => true);
