+  late MemoryExecutionEnv env;
+  late FakeCliIO io;
+
+  setUp(() {
+    env = MemoryExecutionEnv(cwd: '/work');
+    io = FakeCliIO();
+  });
+
+  tearDown(() => io.close());
+
+  AgentCli cliFor(StreamFunction streamFunction) {
