    final bytes = await _readRange(fromOffset, info.size);
    final lines = _splitLines(bytes, fromOffset);
    final entries = await _parseAllLines(lines);
    return SessionChunk(
      entries: entries,
      fileSize: info.size,
      fileMtimeMs: info.mtimeMs,
      hasOlder: false,
      limitOffset: info.size,
    );
  }

