+      if (storage is WindowedSessionStorage) {
+        await storage.ingestAppended();
+      }
+      fresh = await session.getBranch();
+    } on Object catch (error) {
+      io.writeln('trajectory: tail failed: $error');
+      return 1;
+    }
+    for (final line in tailer.tail(fresh)) {
